import React, { useRef, useEffect } from 'react';

const HtmlDialog = ({ onSubmit, defaultText }) => {
  const textRef = useRef(null);

  useEffect(() => {
    // Mettre le focus sur le champ de texte lorsque le composant est monté
    if (textRef.current) {
      textRef.current.focus();
    }
  }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    const text = textRef.current.value;
    onSubmit(text);
  };

  return (
    <form onSubmit={handleSubmit}>
      <br />
      <div>
        <h2>
          <label>1. Saisis ton draft ici</label>
        </h2>
      </div>
      <textarea
        ref={textRef}
        rows="15"
        cols="70"
        defaultValue={defaultText}
      />
      <br /><br />
      <button
        type="submit"
        style={{
          padding: '10px 20px',
          fontSize: '16px',
          backgroundColor: '#4CAF50',
          color: 'white',
          border: 'none',
          borderRadius: '4px',
          cursor: 'pointer'
        }}
      >
        2. Sélectionne les actions à déléguer aux IA
      </button>
    </form>
  );
};

export default HtmlDialog;
